"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[849],{6164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"category","label":"Start Here","items":[{"type":"link","label":"Quickstart","href":"/docs/quickstart/","docId":"quickstart/index","unlisted":false},{"type":"link","label":"Core Concepts","href":"/docs/concepts/","docId":"concepts/index","unlisted":false},{"type":"link","label":"Troubleshooting & FAQ","href":"/docs/troubleshooting/","docId":"troubleshooting/index","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/intro"},{"type":"category","label":"CLI Reference","items":[{"type":"link","label":"lf init","href":"/docs/cli/lf-init","docId":"cli/lf-init","unlisted":false},{"type":"link","label":"lf start","href":"/docs/cli/lf-start","docId":"cli/lf-start","unlisted":false},{"type":"link","label":"lf chat","href":"/docs/cli/lf-chat","docId":"cli/lf-chat","unlisted":false},{"type":"link","label":"lf datasets","href":"/docs/cli/lf-datasets","docId":"cli/lf-datasets","unlisted":false},{"type":"link","label":"lf rag","href":"/docs/cli/lf-rag","docId":"cli/lf-rag","unlisted":false},{"type":"link","label":"lf projects","href":"/docs/cli/lf-projects","docId":"cli/lf-projects","unlisted":false},{"type":"link","label":"lf version","href":"/docs/cli/lf-version","docId":"cli/lf-version","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/cli/"},{"type":"category","label":"Configuration","items":[{"type":"link","label":"Examples","href":"/docs/configuration/example-configs","docId":"configuration/example-configs","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/configuration/"},{"type":"link","label":"RAG","href":"/docs/rag/","docId":"rag/index","unlisted":false},{"type":"link","label":"Models & Runtime","href":"/docs/models/","docId":"models/index","unlisted":false},{"type":"link","label":"Prompts","href":"/docs/prompts/","docId":"prompts/index","unlisted":false},{"type":"link","label":"Deployment","href":"/docs/deployment/","docId":"deployment/index","unlisted":false},{"type":"link","label":"Examples","href":"/docs/examples/","docId":"examples/index","unlisted":false},{"type":"link","label":"Extending","href":"/docs/extending/","docId":"extending/index","unlisted":false},{"type":"link","label":"Contributing","href":"/docs/contributing/","docId":"contributing/index","unlisted":false}]},"docs":{"api/index":{"id":"api/index","title":"API Reference","description":"LlamaFarm provides a comprehensive REST API for managing projects, datasets, chat interactions, and RAG (Retrieval-Augmented Generation) operations. The API follows RESTful conventions and is compatible with OpenAI\'s chat completion format."},"cli/index":{"id":"cli/index","title":"CLI Reference","description":"The lf CLI is your control center for LlamaFarm projects. This reference captures global flags, command behaviours, and examples you can copy into your shell. Each subcommand shares the same auto-start logic: if the server or RAG worker is not running locally, the CLI will launch them (unless you override --server-url).","sidebar":"tutorialSidebar"},"cli/lf-chat":{"id":"cli/lf-chat","title":"lf chat","description":"Send a single prompt to your project\u2019s chat endpoint. By default, responses include RAG context defined in llamafarm.yaml.","sidebar":"tutorialSidebar"},"cli/lf-datasets":{"id":"cli/lf-datasets","title":"lf datasets","description":"Manage datasets defined for your project\u2014create, upload, process, list, and delete ingestion targets used by RAG.","sidebar":"tutorialSidebar"},"cli/lf-init":{"id":"cli/lf-init","title":"lf init","description":"Create a new LlamaFarm project and generate a validated llamafarm.yaml based on server templates.","sidebar":"tutorialSidebar"},"cli/lf-projects":{"id":"cli/lf-projects","title":"lf projects","description":"List the projects available within a namespace on the server.","sidebar":"tutorialSidebar"},"cli/lf-rag":{"id":"cli/lf-rag","title":"lf rag","description":"Query your knowledge base and access RAG maintenance utilities.","sidebar":"tutorialSidebar"},"cli/lf-start":{"id":"cli/lf-start","title":"lf start","description":"Launch the local development stack (API server + RAG worker) and open an interactive chat UI with live config watching.","sidebar":"tutorialSidebar"},"cli/lf-version":{"id":"cli/lf-version","title":"lf version","description":"Display the CLI build information.","sidebar":"tutorialSidebar"},"concepts/index":{"id":"concepts/index","title":"Core Concepts","description":"Understand the moving pieces\u2014projects, sessions, runtimes, and the service architecture\u2014before you customize or extend LlamaFarm.","sidebar":"tutorialSidebar"},"configuration/example-configs":{"id":"configuration/example-configs","title":"Example Configs","description":"Use these snippets as starting points for real projects. Every example validates against the current schema.","sidebar":"tutorialSidebar"},"configuration/index":{"id":"configuration/index","title":"Configuration Guide","description":"Every LlamaFarm project is defined by a single file: llamafarm.yaml. The server validates it against JSON Schema, so missing fields surface as errors instead of hidden defaults. This guide explains each section and shows how to extend the schema responsibly.","sidebar":"tutorialSidebar"},"contributing/index":{"id":"contributing/index","title":"Contributing","description":"We love contributions\u2014from bug fixes and docs edits to new providers and RAG components. This page summarizes expectations and points you to detailed guides.","sidebar":"tutorialSidebar"},"deployment/docker-compose":{"id":"deployment/docker-compose","title":"Docker Compose","description":"Run the server and RAG worker with Docker Compose for reproducible environments."},"deployment/index":{"id":"deployment/index","title":"Deployment","description":"LlamaFarm shards into two primary services: the FastAPI server and the RAG worker (Celery). You can run them locally for development or deploy to your infrastructure using the same configuration.","sidebar":"tutorialSidebar"},"deployment/kubernetes":{"id":"deployment/kubernetes","title":"Kubernetes","description":"Package the server and RAG worker as deployments/stateful sets and manage them with your usual cluster tooling."},"examples/index":{"id":"examples/index","title":"Examples","description":"The repository ships with interactive demos that highlight different retrieval scenarios. Each example lives under examples/ and provides a configuration, sample data, and a script that uses the newest CLI commands (e.g., lf datasets create, lf chat).","sidebar":"tutorialSidebar"},"extending/index":{"id":"extending/index","title":"Extending LlamaFarm","description":"LlamaFarm is designed to be extended. This guide shows how to add new runtime providers, vector stores, parsers, extractors, and CLI commands while keeping schema validation intact.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Welcome to LlamaFarm","description":"LlamaFarm helps you ship retrieval-augmented and agentic AI apps from your laptop to production. It is fully open-source and intentionally extendable\u2014swap model providers, vector stores, parsers, and CLI workflows without rewriting your project.","sidebar":"tutorialSidebar"},"models/index":{"id":"models/index","title":"Models & Runtime","description":"LlamaFarm currently focuses on inference rather than fine-tuning. The runtime section of llamafarm.yaml describes how chat completions are executed\u2014whether against local Ollama, a vLLM gateway, or a remote hosted provider.","sidebar":"tutorialSidebar"},"prompts/index":{"id":"prompts/index","title":"Prompts","description":"Prompts in LlamaFarm are simple but powerful: you define static instructions in llamafarm.yaml, and the runtime merges them with chat history and (optionally) RAG context. This section outlines current capabilities and roadmap plans.","sidebar":"tutorialSidebar"},"quickstart/index":{"id":"quickstart/index","title":"Quickstart","description":"Get the CLI installed, ingest a dataset, and run your first RAG-powered chat in minutes.","sidebar":"tutorialSidebar"},"rag/index":{"id":"rag/index","title":"RAG Guide","description":"LlamaFarm treats retrieval-augmented generation as a first-class, configurable pipeline. This guide explains how strategies, databases, and datasets fit together\u2014and how to operate and extend them.","sidebar":"tutorialSidebar"},"troubleshooting/index":{"id":"troubleshooting/index","title":"Troubleshooting & FAQ","description":"Common symptoms, their causes, and how to resolve them when working with LlamaFarm.","sidebar":"tutorialSidebar"}}}}')}}]);